    """Test if the 'both lose' rule matches"""
    left_trans = [[2 if v != 0 else 0 for v in row] for row in left_grid]
    right_trans = [[2 if v != 0 else 0 for v in row] for row in right_grid]

    correct = 0
    mismatches = []

    for r in range(len(expected_output_lines)):
        out_row = [int(x) for x in expected_output_lines[r].split()]
        computed_row = []
        for c in range(len(out_row)):
            l_val = left_trans[r][c]
            r_val = right_trans[r][c]
            # Rule: if both non-zero, result is 0; otherwise use whichever is non-zero
            if l_val != 0 and r_val != 0:
                res = 0
            elif l_val != 0:
                res = l_val
            elif r_val != 0:
                res = r_val
            else:
                res = 0
